import pytest
from calc import sub

# add all other needed imports here

def test_subtract_positive_integers():
    """Verify that subtracting two positive integers (a=10, b=3) returns the correct positive difference (7)."""
    assert sub(10, 3) == 7

def test_subtract_negative_integers():
    """Verify that subtracting two negative integers (a=-5, b=-3) returns the correct result (-2)."""
    assert sub(-5, -3) == -2

def test_subtract_positive_minus_negative():
    """Verify that subtracting a negative integer from a positive integer (a=5, b=-3) correctly adds the absolute value, returning 8."""
    assert sub(5, -3) == 8

def test_subtract_negative_minus_positive():
    """Verify that subtracting a positive integer from a negative integer (a=-5, b=3) returns the correct negative result (-8)."""
    assert sub(-5, 3) == -8

def test_subtract_zero_minus_positive():
    """Verify that subtracting a positive integer from zero (a=0, b=5) returns the negative of that integer (-5)."""
    assert sub(0, 5) == -5

def test_subtract_positive_minus_zero():
    """Verify that subtracting zero from a positive integer (a=5, b=0) returns the original positive integer (5)."""
    assert sub(5, 0) == 5

def test_subtract_zero_minus_zero():
    """Verify that subtracting zero from zero (a=0, b=0) returns 0."""
    assert sub(0, 0) == 0

def test_subtract_identical_positive_integers():
    """Verify that subtracting identical positive integers (a=10, b=10) returns 0."""
    assert sub(10, 10) == 0

def test_subtract_identical_negative_integers():
    """Verify that subtracting identical negative integers (a=-10, b=-10) returns 0."""
    assert sub(-10, -10) == 0

def test_subtract_large_integers():
    """Verify that subtracting large integers (a=10**18, b=1) handles arbitrarily large numbers correctly without overflow, returning 10**18 - 1."""
    assert sub(10**18, 1) == 10**18 - 1

def test_subtract_large_negative_integers():
    """Verify that subtracting from large negative integers (a=-10**18, b=1) handles arbitrarily large numbers correctly, returning -10**18 - 1."""
    assert sub(-10**18, 1) == -10**18 - 1

def test_subtract_returns_integer_type():
    """Verify that the return type of the subtraction operation is strictly 'int' and not 'float' or other numeric types."""
    result = sub(10, 3)
    assert type(result) is int

