import pytest
from calc import mul

# add all other needed imports here

def test_multiply_two_positive_integers():
    """Verify that multiplying two positive integers returns their correct product (e.g., 2 * 3 = 6)."""
    assert mul(2, 3) == 6

def test_multiply_two_negative_integers():
    """Verify that multiplying two negative integers returns the correct positive product (e.g., -2 * -3 = 6)."""
    assert mul(-2, -3) == 6

def test_multiply_negative_and_positive_integer():
    """Verify that multiplying a negative integer by a positive integer returns the correct negative product (e.g., -2 * 3 = -6)."""
    assert mul(-2, 3) == -6

def test_multiply_positive_and_negative_integer():
    """Verify that multiplying a positive integer by a negative integer returns the correct negative product (e.g., 2 * -3 = -6)."""
    assert mul(2, -3) == -6

def test_multiply_by_zero_first_argument():
    """Verify that multiplying zero by any integer returns 0 (e.g., 0 * 5 = 0)."""
    assert mul(0, 5) == 0

def test_multiply_by_zero_second_argument():
    """Verify that multiplying any integer by zero returns 0 (e.g., 5 * 0 = 0)."""
    assert mul(5, 0) == 0

def test_multiply_zero_by_zero():
    """Verify that multiplying zero by zero returns 0."""
    assert mul(0, 0) == 0

def test_multiply_by_one_first_argument():
    """Verify that multiplying 1 by any integer returns that integer (e.g., 1 * 5 = 5)."""
    assert mul(1, 5) == 5

def test_multiply_by_one_second_argument():
    """Verify that multiplying any integer by 1 returns that integer (e.g., 5 * 1 = 5)."""
    assert mul(5, 1) == 5

def test_multiply_large_positive_integers():
    """Verify that multiplying two large positive integers returns the correct product without overflow or precision errors (e.g., 1000000 * 1000000 = 1000000000000)."""
    assert mul(1000000, 1000000) == 1000000000000

def test_multiply_large_negative_integers():
    """Verify that multiplying two large negative integers returns the correct positive product (e.g., -1000000 * -1000000 = 1000000000000)."""
    assert mul(-1000000, -1000000) == 1000000000000

def test_multiply_returns_integer_type():
    """Verify that the return type of the multiplication result is an integer."""
    result = mul(2, 3)
    assert isinstance(result, int)

